import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span


class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            round_spans([parse_span("09:00-17:15")], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest_step(self):
        spans = [parse_span("08:53-17:07"), parse_span("09:07-10:08")]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:00 (8h 0m)", "09:00-10:15 (1h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_spans([parse_span("09:15-10:45")], 30), ["09:30-11:00 (1h 30m)"]
        )

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([], step)
